            set.items
                .iter()
                .any(|item| item.target == PinTarget::File(*project, path.clone()))
        });
        if !pinned {
            return Err((404, "not_pinned", "no working set pins this file".into()));
        }
        return Ok(ContentJob {
            key: key.clone(),
            source: Source::File {
                root: workspace.project.root.clone(),
                relative: path.clone(),
            },
            view,
