impl RemotePort {
    /// Bind `addr` (port 0 picks one) with the host's TLS configuration.
    /// `wake` runs on a connection thread whenever a request is queued
    /// (an egui `request_repaint`).
    pub fn bind(
        addr: SocketAddr,
        tls: Arc<ServerConfig>,
        wake: impl Fn() + Send + Sync + 'static,
    ) -> io::Result<Self> {
        let listener = TcpListener::bind(addr)?;
        let addr = listener.local_addr()?;
        let (tx, requests) = mpsc::sync_channel(INBOX);
        let (frames_tx, frames) = mpsc::sync_channel(FRAMES);
        let stop = Arc::new(AtomicBool::new(false));
        let shared = Arc::new(Shared {
            tls,
            requests: tx,
            frames: frames_tx,
            wake: Arc::new(wake),
            pools: Pools::default(),
            limits: Limits {
                pair: Mutex::new(RateWindow::new(PAIR_PER_MINUTE, Duration::from_secs(60))),
                info: Mutex::new(RateWindow::new(INFO_PER_MINUTE, Duration::from_secs(60))),
            },
            next_subscriber: AtomicU64::new(1),
        });
        let thread = {
            let stop = Arc::clone(&stop);
            std::thread::Builder::new()
                .name("switchboard-remote".into())
                .spawn(move || {
                    for stream in listener.incoming() {
                        if stop.load(Ordering::SeqCst) {
                            break;
                        }
                        let Ok(stream) = stream else { continue };
                        // Past the pool a stranger is closed at once:
                        // dropping the stream is the close.
                        if shared.pools.unauthenticated.load(Ordering::SeqCst)
                            >= MAX_UNAUTHENTICATED
                        {
                            drop(stream);
                            continue;
                        }
                        shared.pools.unauthenticated.fetch_add(1, Ordering::SeqCst);
                        let shared = Arc::clone(&shared);
                        let _ = std::thread::Builder::new()
                            .name("switchboard-remote-conn".into())
                            .spawn(move || {
                                let paired = AtomicBool::new(false);
                                if let Err(e) = connection(stream, &shared, &paired) {
                                    log::debug!("remote connection: {e}");
                                }
                                if paired.load(Ordering::SeqCst) {
                                    shared.pools.paired.fetch_sub(1, Ordering::SeqCst);
                                } else {
                                    shared.pools.unauthenticated.fetch_sub(1, Ordering::SeqCst);
                                }
                            });
                    }
                })?
        };
        Ok(Self {
            addr,
            requests,
            frames,
            stop,
            thread: Some(thread),
        })
    }

    /// Up to `max` requests that arrived since the last poll, in
    /// arrival order; the rest wait on the channel.
}

/// The address a device on the local network would reach this machine
/// at: the one the system routes outward on. No packet is sent; a
/// connected UDP socket only chooses a source address. `None` with no
/// network.
#[must_use]
pub fn local_address() -> Option<IpAddr> {
    let socket = UdpSocket::bind("0.0.0.0:0").ok()?;
    socket.connect("192.0.2.1:9").ok()?;
    socket
        .local_addr()
        .ok()
        .map(|a| a.ip())
        .filter(|ip| !ip.is_loopback())
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Bind the remote port as the identity says: loopback until the
    /// owner allows the local network. `wake` runs on a connection
    /// thread whenever a request is queued. Refused for a read-only
    /// instance and for one whose key is unavailable.
    pub fn listen_remote(
        &mut self,
        wake: impl Fn() + Send + Sync + 'static,
    ) -> io::Result<SocketAddr> {
        self.remote_wake = Some(Arc::new(wake));
        self.bind_remote()
    }

    fn bind_remote(&mut self) -> io::Result<SocketAddr> {
        self.remote = None;
        self.remote_bound = None;
        self.services.advertiser.withdraw();
