        ("POST", "/api/v1/projects".into()),
        ("DELETE", format!("/api/v1/sessions/{session}")),
        ("GET", "/api/v2/projects".into()),
    ] {
        let (status, reply) = call(&mut port, method, &path, t, r#"{"text":"hi"}"#);
